import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"分支限界 (Branch & Bound)","description":"","frontmatter":{},"headers":[],"relativePath":"dsa/algorithms/branch-bound.md","filePath":"dsa/algorithms/branch-bound.md","lastUpdated":1788475713000}'),l={name:"dsa/algorithms/branch-bound.md"};function i(o,a,r,p,c,d){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="分支限界-branch-bound" tabindex="-1">分支限界 (Branch &amp; Bound) <a class="header-anchor" href="#分支限界-branch-bound" aria-label="Permalink to &quot;分支限界 (Branch &amp; Bound)&quot;">​</a></h1><h2 id="与回溯的关系" tabindex="-1">与回溯的关系 <a class="header-anchor" href="#与回溯的关系" aria-label="Permalink to &quot;与回溯的关系&quot;">​</a></h2><ul><li>回溯目标是&quot;找到所有/任一组解&quot;;</li><li>分支限界目标是&quot;找最优解&quot;, 多了一个<strong>下界估计</strong>: 当某个分支的&quot;乐观估计已经差于当前最优&quot;立刻剪.</li></ul><h2 id="模板" tabindex="-1">模板 <a class="header-anchor" href="#模板" aria-label="Permalink to &quot;模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>best = INF</span></span>
<span class="line"><span>Q = heap of (state, lowerBound)   # 优先队列按 lowerBound 升序</span></span>
<span class="line"><span>push (initial_state, lowerBound(initial_state))</span></span>
<span class="line"><span>while Q:</span></span>
<span class="line"><span>  state, lb = pop Q</span></span>
<span class="line"><span>  if lb &gt;= best: continue       # 剪枝</span></span>
<span class="line"><span>  if terminal(state):</span></span>
<span class="line"><span>    if cost(state) &lt; best: best = cost(state)</span></span>
<span class="line"><span>    continue</span></span>
<span class="line"><span>  for sub in expand(state):</span></span>
<span class="line"><span>    lb = lowerBound(sub)</span></span>
<span class="line"><span>    if lb &lt; best: push(sub, lb)</span></span></code></pre></div><h2 id="不同的搜索策略" tabindex="-1">不同的搜索策略 <a class="header-anchor" href="#不同的搜索策略" aria-label="Permalink to &quot;不同的搜索策略&quot;">​</a></h2><ul><li><strong>DFS + B&amp;B</strong>: 内存小, 深度优先; 只保留当前路径. 常用于 TSP 大输入.</li><li><strong>BFS + B&amp;B</strong> (=Best-First Search): 优先队列里挑 lb 最小的, 类似 A* 思想.</li><li><strong>iterative deepening</strong>: 迭代加深, 结合 DFS 内存友好与 BFS 完备性.</li></ul><h2 id="下界设计的艺术" tabindex="-1">下界设计的艺术 <a class="header-anchor" href="#下界设计的艺术" aria-label="Permalink to &quot;下界设计的艺术&quot;">​</a></h2><p>下界越紧、剪枝越狠、运行越快. 例: TSP 一个简单紧的下界是 MST 权值 + 两条最小边修正; 0/1 背包下界是&quot;剩余容量用最优单价物品填满&quot;.</p><h2 id="经典应用" tabindex="-1">经典应用 <a class="header-anchor" href="#经典应用" aria-label="Permalink to &quot;经典应用&quot;">​</a></h2><ul><li>TSP: Held-Karp / B&amp;B / cutting-plane;</li><li>0/1 KP: 分支限界 + 上界 (部分 KP);</li><li>整数规划: CPLEX / Gurobi 内部其中一类算法.</li></ul><h2 id="易错" tabindex="-1">易错 <a class="header-anchor" href="#易错" aria-label="Permalink to &quot;易错&quot;">​</a></h2><ol><li><strong>下界不松不紧</strong>: 完全松 = 退化为回溯; 太紧 = 计算 lb 自己贵到不值得.</li><li><strong>best 初始化</strong>: 用贪心算法跑出一个上界作为 best 初值, 极大加速.</li><li><strong>优先队列操作过度</strong>: 复杂 heap 操作可能让常数翻倍.</li></ol>`,13)])])}const b=n(l,[["render",i]]);export{u as __pageData,b as default};
